import os
import unicodedata
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file, abort
from functools import wraps
import re

app = Flask(__name__)
app.config['UPLOAD_ROOT'] = '/var/app/uploads'
app.config['SECRET_KEY'] = secrets.token_hex(32)

# Rate limiting state
_request_counts = {}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if not token:
            abort(401)
        # Constant-time comparison for auth token
        expected = hmac.new(app.config['SECRET_KEY'].encode(), 
                          b'auth-token', hashlib.sha256).hexdigest()
        if not hmac.compare_digest(token, expected):
            abort(403)
        return f(*args, **kwargs)
    return decorated

def rate_limit(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        client_ip = request.remote_addr
        count = _request_counts.get(client_ip, 0)
        if count > 100:
            abort(429)
        _request_counts[client_ip] = count + 1
        return f(*args, **kwargs)
    return decorated

class PathValidator:
    """Multi-layer path validation to prevent directory traversal."""

    BLOCKED_PATTERNS = [
        re.compile(r'\.\./'),
        re.compile(r'/\.\./'),
        re.compile(r'\.\.\\'),
        re.compile(r'\\\.\.\\'),
        re.compile(r'%2e%2e', re.IGNORECASE),
        re.compile(r'%2f', re.IGNORECASE),
        re.compile(r'%5c', re.IGNORECASE),
    ]

    BLOCKED_CHARS = set('\x00\r\n')

    @staticmethod
    def sanitize_filename(filename: str) -> str:
        """Remove null bytes and control characters."""
        return ''.join(c for c in filename if c not in PathValidator.BLOCKED_CHARS)

    @staticmethod
    def check_traversal_patterns(path: str) -> bool:
        """Returns True if path is safe (no traversal patterns found)."""
        for pattern in PathValidator.BLOCKED_PATTERNS:
            if pattern.search(path):
                return False
        return True

    @staticmethod
    def validate_within_root(filepath: str, root: str) -> bool:
        """Ensure resolved path is within the root directory."""
        resolved = os.path.realpath(filepath)
        root_resolved = os.path.realpath(root)
        return resolved.startswith(root_resolved + os.sep) or resolved == root_resolved

    @staticmethod  
    def normalize_path(path: str) -> str:
        """Normalize unicode characters in path to NFC form."""
        return unicodedata.normalize('NFC', path)


def resolve_user_path(user_input: str, base_dir: str) -> str:
    """Safely resolve a user-provided path within base_dir.

    Security layers:
    1. Sanitize control characters
    2. Check for traversal patterns  
    3. Validate path stays within root
    4. Normalize unicode
    """
    # Layer 1: Remove dangerous characters
    cleaned = PathValidator.sanitize_filename(user_input)

    # Layer 2: Check for traversal patterns
    if not PathValidator.check_traversal_patterns(cleaned):
        raise ValueError("Path contains traversal sequences")

    # Layer 3: Construct and validate full path
    full_path = os.path.join(base_dir, cleaned)
    if not PathValidator.validate_within_root(full_path, base_dir):
        raise ValueError("Path escapes root directory")

    # Layer 4: Normalize unicode for consistent storage/retrieval
    normalized_path = PathValidator.normalize_path(full_path)

    return normalized_path


@app.route('/api/files/<path:filepath>', methods=['GET'])
@require_auth
@rate_limit
def get_file(filepath):
    """Retrieve a file from the uploads directory."""
    try:
        safe_path = resolve_user_path(filepath, app.config['UPLOAD_ROOT'])
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    if not os.path.isfile(safe_path):
        abort(404)

    return send_file(safe_path)


@app.route('/api/files/<path:filepath>', methods=['DELETE'])
@require_auth
@rate_limit
def delete_file(filepath):
    """Delete a file from the uploads directory."""
    try:
        safe_path = resolve_user_path(filepath, app.config['UPLOAD_ROOT'])
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    if not os.path.isfile(safe_path):
        abort(404)

    os.remove(safe_path)
    return jsonify({'status': 'deleted'}), 200


@app.route('/api/files', methods=['POST'])
@require_auth
@rate_limit
def upload_file():
    """Upload a file to the uploads directory."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    f = request.files['file']
    dest_path = request.form.get('path', '')

    if not dest_path:
        return jsonify({'error': 'No destination path'}), 400

    try:
        safe_path = resolve_user_path(dest_path, app.config['UPLOAD_ROOT'])
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    os.makedirs(os.path.dirname(safe_path), exist_ok=True)
    f.save(safe_path)

    return jsonify({'status': 'uploaded', 'path': dest_path}), 201


if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_ROOT'], exist_ok=True)
    app.run(host='127.0.0.1', port=8080, debug=False)
